template <class T>
inline bool isNumeric(const T in) {
    return (chartype_table[static_cast<size_t>(in)] == 1);
}

template <class T>
inline bool isNotEndOfToken(T *in, T *end) {
    return ('}' != *in && ',' != *in && !isSpace(*in) && ')' != *in && in != end);
}

